-- E8-6: notices per person (R128) and reminders generated by a server clock (R129, R132).
-- para_user_id null = for the owner(s), as every notice was until now; otherwise only that person sees it.
alter table public.avisos
  add column para_user_id uuid references auth.users (id) on delete cascade,
  add column chave text,                                            -- one reminder per event and person: reruns add nothing
  add column atividade_id uuid references public.atividades (id) on delete cascade,
  add column reserva_id uuid references public.reservas (id) on delete cascade,
  add column saida_id uuid references public.saidas (id) on delete cascade,
  add constraint avisos_chave_unica unique (agencia_id, chave);
create index avisos_para_idx on public.avisos (para_user_id, lido_em, criado_em desc);

drop policy avisos_select on public.avisos;
drop policy avisos_update on public.avisos;
create policy avisos_select on public.avisos for select to authenticated using (
  (para_user_id is null and private.e_dono(agencia_id))
  or (para_user_id = (select auth.uid()) and private.e_membro(agencia_id)));
create policy avisos_update on public.avisos for update to authenticated
  using ((para_user_id is null and private.e_dono(agencia_id)) or (para_user_id = (select auth.uid()) and private.e_membro(agencia_id)))
  with check ((para_user_id is null and private.e_dono(agencia_id)) or (para_user_id = (select auth.uid()) and private.e_membro(agencia_id)));

-- R129. Times are in Brazil (UTC-3). Activities older than 2 days are left alone, so the first run does not flood anyone. ⚠️
create function public.gerar_lembretes(p_agora timestamptz default now()) returns integer
  language plpgsql security definer set search_path = '' as $$
declare
  v_hoje date := (p_agora at time zone 'America/Sao_Paulo')::date;
  v_total integer := 0;
  v_n integer;
begin
  -- Activity due now: for the person responsible (or whoever created it), while still a member.
  insert into public.avisos (agencia_id, tipo, titulo, cliente_nome, valor_centavos, para_user_id, chave, atividade_id)
  select a.agencia_id, 'atividade_agora', a.titulo, c.nome, 0, m.user_id, 'agora:' || a.id, a.id
  from public.atividades a
  join public.clientes c on c.id = a.cliente_id
  join public.membros m on m.user_id = coalesce(a.responsavel_id, a.criado_por) and m.agencia_id = a.agencia_id
  where a.status = 'pendente' and a.quando <= p_agora and a.quando > p_agora - interval '1 hour'
  on conflict (agencia_id, chave) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- Still pending one hour later: one "late" reminder, never repeated.
  insert into public.avisos (agencia_id, tipo, titulo, cliente_nome, valor_centavos, para_user_id, chave, atividade_id)
  select a.agencia_id, 'atividade_atrasada', a.titulo, c.nome, 0, m.user_id, 'atrasada:' || a.id, a.id
  from public.atividades a
  join public.clientes c on c.id = a.cliente_id
  join public.membros m on m.user_id = coalesce(a.responsavel_id, a.criado_por) and m.agencia_id = a.agencia_id
  where a.status = 'pendente' and a.quando <= p_agora - interval '1 hour' and a.quando > p_agora - interval '2 days'
  on conflict (agencia_id, chave) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- Balance due today: the owner(s) and the seller (when the seller is not an owner).
  insert into public.avisos (agencia_id, tipo, titulo, cliente_nome, valor_centavos, para_user_id, chave, reserva_id)
  select r.agencia_id, 'cobranca_vencendo', p.nome, c.nome, r.saldo_centavos, d.para, 'cobranca:' || r.id || ':' || v_hoje || ':' || coalesce(d.para::text, 'dono'), r.id
  from public.v_reservas_saldo r
  join public.reservas rr on rr.id = r.id
  join public.saidas s on s.id = r.saida_id
  join public.passeios p on p.id = s.passeio_id
  join public.clientes c on c.id = r.cliente_id
  cross join lateral (
    select null::uuid as para
    union all
    select m.user_id from public.membros m where m.user_id = rr.vendedor_id and m.agencia_id = r.agencia_id and m.papel = 'vendedor'
  ) d
  where r.situacao = 'ativa' and r.saldo_centavos > 0 and r.vencimento_saldo = v_hoje
  on conflict (agencia_id, chave) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- Departure in 2 days: the owner(s) and each seller with an active reservation on it.
  insert into public.avisos (agencia_id, tipo, titulo, cliente_nome, valor_centavos, para_user_id, chave, saida_id)
  select s.agencia_id, 'saida_chegando', p.nome, '', 0, d.para, 'saida:' || s.id || ':' || coalesce(d.para::text, 'dono'), s.id
  from public.saidas s
  join public.passeios p on p.id = s.passeio_id
  cross join lateral (
    select null::uuid as para
    union
    select m.user_id from public.reservas rr
    join public.membros m on m.user_id = rr.vendedor_id and m.agencia_id = s.agencia_id and m.papel = 'vendedor'
    where rr.saida_id = s.id and rr.situacao = 'ativa'
  ) d
  where s.situacao = 'aberta' and s.data = v_hoje + 2
  on conflict (agencia_id, chave) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  return v_total;
end;
$$;
revoke all on function public.gerar_lembretes(timestamptz) from public, anon, authenticated;
grant execute on function public.gerar_lembretes(timestamptz) to service_role;
